create extension if not exists "uuid-ossp";
create table if not exists public.travelos_leads(id uuid primary key default uuid_generate_v4(),session_id uuid not null unique,franchisee_id text not null,captured_at timestamptz not null,first_name text not null,last_name text,email text not null,phone text,existing_client_id text,destination text not null,duration_days integer not null check(duration_days>=1),estimated_budget_gbp numeric(10,2) not null check(estimated_budget_gbp>=0),travelers jsonb not null,preferences jsonb,memory_vector_references jsonb,priority_level text not null check(priority_level in('HIGH','MEDIUM','LOW')),confidence_score numeric(3,2) not null check(confidence_score between 0 and 1),intent_signals jsonb not null,scoring_version text not null default 'v1.0.0',suggested_next_step text not null,followup_at timestamptz,source text not null default 'atlas_concierge',status text not null default 'NEW' check(status in('NEW','PROCESSING','ACTION_REQUIRED','PROPOSAL_GENERATED','CONTACTED','CLOSED')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.travelos_events(id uuid primary key default uuid_generate_v4(),trace_id uuid not null,event_type text not null,aggregate_id uuid not null,session_id uuid not null,payload jsonb not null,status text not null default 'PENDING' check(status in('PENDING','PROCESSING','COMPLETED','FAILED','DEAD_LETTER')),attempts integer not null default 0,max_attempts integer not null default 3,worker_id text,locked_at timestamptz,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_travelos_events_queue on public.travelos_events(status,created_at) where status in('PENDING','PROCESSING');
create index if not exists idx_travelos_events_trace_id on public.travelos_events(trace_id);
create table if not exists public.travelos_proposals(id uuid primary key default uuid_generate_v4(),lead_id uuid not null references public.travelos_leads(id),session_id uuid not null,source_event_id uuid not null unique references public.travelos_events(id),options jsonb not null,source_snapshot jsonb not null,engine_version text not null default 'v1.0.0',status text not null default 'READY' check(status in('DRAFT','READY','FAILED')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.telemetry_traces(id uuid primary key default uuid_generate_v4(),trace_id uuid not null,session_id uuid not null,span_name text not null,timestamp_epoch_ms bigint not null,timestamp_utc timestamptz not null,service_id text not null,metadata jsonb,created_at timestamptz not null default now());
create index if not exists idx_telemetry_trace_id on public.telemetry_traces(trace_id);
alter table public.travelos_leads enable row level security;alter table public.travelos_events enable row level security;alter table public.travelos_proposals enable row level security;alter table public.telemetry_traces enable row level security;
drop policy if exists "service role leads" on public.travelos_leads;create policy "service role leads" on public.travelos_leads for all to service_role using(true) with check(true);
drop policy if exists "service role events" on public.travelos_events;create policy "service role events" on public.travelos_events for all to service_role using(true) with check(true);
drop policy if exists "service role proposals" on public.travelos_proposals;create policy "service role proposals" on public.travelos_proposals for all to service_role using(true) with check(true);
drop policy if exists "service role telemetry" on public.telemetry_traces;create policy "service role telemetry" on public.telemetry_traces for all to service_role using(true) with check(true);
drop policy if exists "franchisee leads select" on public.travelos_leads;create policy "franchisee leads select" on public.travelos_leads for select to authenticated using(franchisee_id=(auth.jwt()->>'franchisee_id'));
drop policy if exists "franchisee proposals select" on public.travelos_proposals;create policy "franchisee proposals select" on public.travelos_proposals for select to authenticated using(exists(select 1 from public.travelos_leads l where l.id=lead_id and l.franchisee_id=(auth.jwt()->>'franchisee_id')));
create or replace function public.set_updated_at_timestamp() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end; $$;
drop trigger if exists trg_leads_updated_at on public.travelos_leads;create trigger trg_leads_updated_at before update on public.travelos_leads for each row execute function public.set_updated_at_timestamp();
drop trigger if exists trg_events_updated_at on public.travelos_events;create trigger trg_events_updated_at before update on public.travelos_events for each row execute function public.set_updated_at_timestamp();
drop trigger if exists trg_proposals_updated_at on public.travelos_proposals;create trigger trg_proposals_updated_at before update on public.travelos_proposals for each row execute function public.set_updated_at_timestamp();
create or replace function public.claim_next_travelos_event(p_worker_id text,p_lease_duration_seconds integer default 60) returns setof public.travelos_events language plpgsql as $$ declare v_event_id uuid; begin update public.travelos_events set status='DEAD_LETTER',last_error='Lease expired and max retries exceeded',locked_at=null,updated_at=now() where status='PROCESSING' and locked_at<now()-(p_lease_duration_seconds||' seconds')::interval and attempts>=max_attempts; select id into v_event_id from public.travelos_events where (status='PENDING' or(status='PROCESSING' and locked_at<now()-(p_lease_duration_seconds||' seconds')::interval)) and attempts<max_attempts order by created_at asc for update skip locked limit 1; if v_event_id is null then return;end if;return query update public.travelos_events set status='PROCESSING',worker_id=p_worker_id,locked_at=now(),attempts=attempts+1,updated_at=now() where id=v_event_id returning *;end; $$;
create or replace function public.commit_proposal_transaction(p_lead_id uuid,p_session_id uuid,p_source_event_id uuid,p_options jsonb,p_source_snapshot jsonb,p_engine_version text) returns uuid language plpgsql as $$ declare v_proposal_id uuid;begin insert into public.travelos_proposals(lead_id,session_id,source_event_id,options,source_snapshot,engine_version,status) values(p_lead_id,p_session_id,p_source_event_id,p_options,p_source_snapshot,p_engine_version,'READY') on conflict(source_event_id) do update set updated_at=now() returning id into v_proposal_id;update public.travelos_leads set status='PROPOSAL_GENERATED',updated_at=now() where id=p_lead_id;update public.travelos_events set status='COMPLETED',locked_at=null,updated_at=now() where id=p_source_event_id;return v_proposal_id;end; $$;